<template>
    <div class="level-wizard-backdrop" role="presentation" @click.self="$emit('close')">
        <section class="level-wizard" role="dialog" aria-modal="true" aria-labelledby="level-wizard-title">
            <header class="level-wizard-header"><div><p class="sheet-eyebrow">PROGRESIÓN DEL PERSONAJE</p><h2 id="level-wizard-title">Subir de nivel: {{ characterClass.class }}</h2><p>Nivel {{ options?.current_class_level || characterClass.level }} → {{ options?.next_class_level || Number(characterClass.level) + 1 }}</p></div><button type="button" class="level-wizard-close" aria-label="Cerrar" @click="$emit('close')">×</button></header>
            <nav class="level-wizard-steps" aria-label="Pasos de subida de nivel"><button v-for="(label, index) in stepLabels" :key="label" type="button" :class="{ active: step === index, done: step > index }" @click="step = index" :disabled="saving || !options || index > highestStep">{{ index + 1 }}. {{ label }}</button></nav>
            <p v-if="loading" class="sheet-state">Consultando la progresión de este nivel...</p><p v-else-if="error" class="error-message" role="alert">{{ error }}</p>
            <template v-else>
                <div class="level-wizard-content">
                    <section v-if="step === 0"><h3>Qué obtiene este nivel</h3><p>Vas a aplicar únicamente el siguiente nivel de esta clase. Si quieres avanzar varios niveles, tendrás que completar este asistente de nuevo para cada uno.</p><ul v-if="options.features?.length" class="level-wizard-feature-list"><li v-for="feature in options.features" :key="feature.index || feature.name"><strong>{{ feature.name }}</strong><p v-if="feature.desc">{{ Array.isArray(feature.desc) ? feature.desc.join(' ') : feature.desc }}</p></li></ul><p v-else class="sheet-empty">La API no ha devuelto rasgos nuevos para este nivel.</p><p><strong>Nivel total después de confirmar:</strong> {{ options.character_level_after }}</p><p v-if="options.has_asi" class="level-wizard-highlight">Este nivel concede una mejora de características: podrás elegir una dote o mejorar tus características.</p></section>
                    <section v-else-if="step === 1"><h3>Puntos de golpe</h3><p>Dado de golpe: d{{ options.hit_die }}. Se aplica tu modificador positivo de Constitución; los modificadores negativos no reducen los puntos obtenidos, según la regla acordada.</p><label class="level-wizard-field">Método<select v-model="hpMethod"><option value="average">Promedio ({{ Math.floor(options.hit_die / 2) }})</option><option value="manual">Tirada manual</option></select></label><label v-if="hpMethod === 'manual'" class="level-wizard-field">Resultado del dado<select v-model.number="hpRoll"><option v-for="pip in options.hit_die" :key="pip" :value="pip">{{ pip }}</option></select></label><p class="level-wizard-highlight">Puntos de golpe que se añadirán: {{ hpGain }}</p></section>
                    <section v-else-if="step === 2"><h3>Subclase</h3><template v-if="options.subclass_required"><p>Este nivel requiere elegir la subclase de {{ characterClass.class }}.</p><label class="level-wizard-field">Subclase<select v-model="subclassIndex"><option value="">Selecciona una subclase</option><option v-for="subclass in options.subclasses" :key="subclass.index" :value="subclass.index">{{ subclass.name }}</option></select></label></template><p v-else class="sheet-empty">No tienes que elegir una subclase en este nivel.</p></section>
                    <section v-else-if="step === 3"><h3>Dote o mejora de características</h3><p v-if="!options.has_asi" class="sheet-empty">Este nivel no concede una mejora de características ni una dote. Continúa al resumen.</p><template v-else><div class="level-wizard-choice"><label><input type="radio" value="asi" v-model="asiChoice"> Mejorar características</label><label><input type="radio" value="feat" v-model="asiChoice"> Elegir una dote</label></div><template v-if="asiChoice === 'asi'"><label class="level-wizard-field">Distribución<select v-model="asiMode"><option value="two">+1 a dos características</option><option value="one">+2 a una característica</option></select></label><label class="level-wizard-field">Primera característica<select v-model="firstAbility"><option value="">Selecciona</option><option v-for="ability in abilities" :key="ability.key" :value="ability.key" :disabled="effectiveScore(ability.key) + (asiMode === 'one' ? 2 : 1) > 20">{{ ability.name }} ({{ effectiveScore(ability.key) }})</option></select></label><label v-if="asiMode === 'two'" class="level-wizard-field">Segunda característica<select v-model="secondAbility"><option value="">Selecciona</option><option v-for="ability in abilities" :key="ability.key" :value="ability.key" :disabled="ability.key === firstAbility || effectiveScore(ability.key) >= 20">{{ ability.name }} ({{ effectiveScore(ability.key) }})</option></select></label></template><template v-else><label class="level-wizard-field">Dote<select v-model="featIndex" @change="loadFeat"><option value="">Selecciona una dote</option><option v-for="feat in options.feats" :key="feat.index" :value="feat.index">{{ feat.name }}</option></select></label><label v-if="featAbilityOptions.length" class="level-wizard-field">Mejora que concede la dote (+1)<select v-model="featAbility"><option value="">Selecciona una característica</option><option v-for="ability in featAbilityOptions" :key="ability.key" :value="ability.key" :disabled="effectiveScore(ability.key) >= 20">{{ ability.name }} ({{ effectiveScore(ability.key) }})</option></select></label><article v-if="featDetail" class="level-wizard-feat-detail"><h4>{{ featDetail.name }}</h4><p v-for="(paragraph, index) in featDetail.desc || []" :key="index">{{ paragraph }}</p><p v-if="featDetail.prerequisites?.length"><strong>Requisitos:</strong> {{ featDetail.prerequisites.map(item => item.type || item.name || 'Requisito').join(', ') }}</p></article></template></template></section>
                    <section v-else><h3>Revisar subida de nivel</h3><dl class="level-wizard-summary"><div><dt>Clase</dt><dd>{{ characterClass.class }}</dd></div><div><dt>Nivel de clase</dt><dd>{{ options.next_class_level }}</dd></div><div><dt>Puntos de golpe</dt><dd>+{{ hpGain }}</dd></div><div v-if="subclassIndex"><dt>Subclase</dt><dd>{{ options.subclasses.find(item => item.index === subclassIndex)?.name }}</dd></div><div v-if="featIndex"><dt>Dote</dt><dd>{{ featDetail?.name || featIndex }}<template v-if="featAbility"> · {{ abilityName(featAbility) }} +1</template></dd></div><div v-for="choice in asiPayload" :key="choice.ability"><dt>Mejora</dt><dd>{{ abilityName(choice.ability) }} +{{ choice.increase }}</dd></div></dl><p>Al confirmar, el nivel, los puntos de golpe y las elecciones quedarán guardados en el historial del personaje.</p></section>
                </div>
                <p v-if="formError" class="error-message" role="alert">{{ formError }}</p><footer class="level-wizard-footer"><button type="button" class="secondary-button" @click="step = Math.max(0, step - 1)" :disabled="step === 0 || saving">Anterior</button><span>Paso {{ step + 1 }} de {{ stepLabels.length }}</span><button v-if="step < stepLabels.length - 1" type="button" class="primary-button" @click="nextStep">Siguiente</button><button v-else type="button" class="primary-button" :disabled="saving" @click="confirmLevelUp">{{ saving ? 'Guardando...' : 'Confirmar subida de nivel' }}</button></footer>
            </template>
        </section>
    </div>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue';
import api from '../services/api';
const props = defineProps({ character: { type: Object, required: true }, characterClass: { type: Object, required: true } });
const emit = defineEmits(['close', 'completed']);
const stepLabels = ['Resumen', 'Puntos de golpe', 'Subclase', 'Dote o mejora', 'Confirmar'];
const highestStep = ref(0);
const abilities = [{key:'strength',name:'Fuerza'},{key:'dexterity',name:'Destreza'},{key:'constitution',name:'Constitución'},{key:'intelligence',name:'Inteligencia'},{key:'wisdom',name:'Sabiduría'},{key:'charisma',name:'Carisma'}];
const loading=ref(true), saving=ref(false), error=ref(''), formError=ref(''), options=ref(null), step=ref(0), hpMethod=ref('average'), hpRoll=ref(1), subclassIndex=ref(''), asiChoice=ref('asi'), asiMode=ref('two'), firstAbility=ref(''), secondAbility=ref(''), featIndex=ref(''), featDetail=ref(null), featAbility=ref('');
const hpGain=computed(()=> (hpMethod.value==='manual'?Number(hpRoll.value):Math.floor(Number(options.value?.hit_die||0)/2))+Math.max(0,Number(options.value?.ability_scores?.constitution?.modifier||0)));
const asiPayload=computed(()=>{if(asiChoice.value!=='asi'||!options.value?.has_asi||!firstAbility.value)return[];if(asiMode.value==='one')return[{ability:firstAbility.value,increase:2}];if(!secondAbility.value||secondAbility.value===firstAbility.value)return[];return[{ability:firstAbility.value,increase:1},{ability:secondAbility.value,increase:1}];});
function effectiveScore(key){return Number(options.value?.ability_scores?.[key]?.effective_score??props.character[key]??10)}
const featAbilityOptions=computed(()=>{const text=(featDetail.value?.desc||[]).join(' ');if(/one ability score of your choice/i.test(text))return abilities;if(!/(increase|increases) your .{1,90} score by 1/i.test(text))return[];const found=abilities.filter(item=>new RegExp(item.name,'i').test(text));return found;});
function abilityName(key){return abilities.find(item=>item.key===key)?.name||key}
async function loadFeat(){featDetail.value=null;featAbility.value='';if(!featIndex.value)return;try{const response=await api.get(`/dnd/feats/${featIndex.value}`);featDetail.value=response.data}catch(_){formError.value='No se pudo cargar la descripción de la dote.'}}
function nextStep(){formError.value='';if(step.value===2&&options.value.subclass_required&&!subclassIndex.value){formError.value='Selecciona una subclase para continuar.';return}if(step.value===3&&options.value.has_asi){if(asiChoice.value==='feat'&&!featIndex.value){formError.value='Selecciona una dote.';return}if(asiChoice.value==='feat'&&featAbilityOptions.value.length&&!featAbility.value){formError.value='Selecciona la característica que mejora esta dote.';return}if(asiChoice.value==='asi'&&!asiPayload.value.length){formError.value='Completa la distribución de características.';return}}step.value++;highestStep.value=Math.max(highestStep.value,step.value)}
async function confirmLevelUp(){saving.value=true;formError.value='';try{await api.post(`/characters/${props.character.id}/classes/${props.characterClass.id}/level-up`,{hp_method:hpMethod.value,...(hpMethod.value==='manual'?{base_hp_gained:hpRoll.value}:{}),...(subclassIndex.value?{subclass_index:subclassIndex.value}:{}),...(featIndex.value&&asiChoice.value==='feat'?{feat_index:featIndex.value}:{}),...(featAbility.value&&asiChoice.value==='feat'?{feat_ability_increase:featAbility.value}:{}),...(asiPayload.value.length?{ability_score_increases:asiPayload.value}:{})});emit('completed')}catch(err){formError.value=Object.values(err.response?.data?.errors||{}).flat()[0]||err.response?.data?.message||'No se pudo completar la subida de nivel.'}finally{saving.value=false}}
onMounted(async()=>{try{const response=await api.get(`/characters/${props.character.id}/classes/${props.characterClass.id}/level-up-options`);options.value=response.data;hpRoll.value=Math.floor(Number(response.data.hit_die)/2)||1}catch(err){error.value=err.response?.data?.message||'No se pudo consultar la progresión de este nivel.'}finally{loading.value=false}});
</script>
